import { editProjectGeneralInformation } from '~/client';
import type {
  EditProjectGeneralInformationResponse,
  ProjectEditGeneralInfoRequest,
  ProjectGeneralInfoResponse,
  ProjectType,
} from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useEditProjectGeneralInfo = defineMutation(() => {
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (params: {
      data: ProjectEditGeneralInfoRequest;
      projectId: string;
    }): Promise<EditProjectGeneralInformationResponse> =>
      editProjectGeneralInformation({
        composable: '$fetch',
        path: { project_id: params.projectId },
        body: ref(params.data),
      }),
    onSuccess: (_, params) => {
      const queryCache = useQueryCache();
      const data = queryCache.getQueryData<ProjectGeneralInfoResponse>(['project-general-info', params.projectId]);
      queryCache.setQueryData(['project-general-info', params.projectId], () => {
        return {
          ...params.data,
          type: data?.type,
          time_zone: data?.time_zone,
          regions: data?.type === 'signature' ? params.data.regions : data?.regions,
        };
      });
      queryCache.invalidateQueries({ key: ['project-edit-tabs-status', params.projectId] });
      showToastSuccess(`Project general information edited successfully`);
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    editProjectGeneralInfo: mutateAsync,
    isEditProjectGeneralInfoLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
