import { getProjectGeneralInformation } from '~/client';

export const useProjectGeneralInfo = defineQuery(() => {
  const route = useRoute('projects-id-edit-general-information');
  const projectId = computed(() => route.params?.id);

  const {
    data: projectGeneralInfo,
    error,
    isLoading,
  } = useQuery({
    key: () => ['project-general-info', projectId.value],
    query: () => getProjectGeneralInformation({ composable: '$fetch', path: { project_id: projectId.value } }),
    staleTime: 0,
    enabled: () => useRoute().name === 'projects-id-edit-general-information' && !!projectId.value,
  });

  return {
    projectId,
    projectGeneralInfo,
    regions: computed(() => projectGeneralInfo.value?.regions || []),
    error,
    isLoading,
  };
});
