<template>
  <AppLoader v-if="isLoading" subject="general information" />
  <AppError v-else-if="error" :error="error" title="Failed to load project general information" />
  <AppEmpty v-else-if="!projectGeneralInfo" subject="project general information" />
  <form v-else id="editProjectGeneralInfoForm" class="grid grid-cols-8 gap-6" @submit="onSubmit">
    <ProjectCreateEditFormMain
      :date-range-picker-value="dateRangePickerValue"
      :set-date-range-picker-value="setDateRangePickerValue"
      type="edit"
      :project-type="projectTypeValue"
      :project-timezone="values.time_zone"
    />
    <ProjectCreateEditFormRegions :items="formRegions" :project-type="projectTypeValue" />
    <Card class="col-span-8 h-fit">
      <CardContent class="flex justify-end">
        <Button
          type="submit"
          :loading="isEditProjectGeneralInfoLoading"
          :disabled="isEqual(savedDataNormalized, processedDataFromForm) || isEditProjectGeneralInfoLoading"
        >
          Save
        </Button>
      </CardContent>
    </Card>
  </form>
  <NavigationGuard
    v-if="projectGeneralInfo && isAuthenticated"
    :saved-data="savedDataNormalized"
    :changed-data="processedDataFromForm"
    title="Warning"
    description="You have some unsaved changes on this tab! Save them before switching to another tab."
    confirm-text="Discard Changes"
  />
</template>

<script lang="ts" setup>
import { useForm } from 'vee-validate';
import { isEqual } from 'lodash';
import { formSchema } from '~/constants/validationSchemas/projectEditGeneralInfoSpecific';
import { useProjectGeneralInfo } from '~/queries/project/edit/generalInfo';
import { useEditProjectGeneralInfo } from '~/mutations/project/edit/generalInfo';
import type { ProjectType } from '~/client';

definePageMeta({
  backGroup: 'project-edit',
  roles: ['admin'],
  backLabel: 'project edit',
});

useSeoMeta({
  title: computed(() => 'Edit Project'),
  description: computed(() => 'Edit your project general information here.'),
});

const { projectGeneralInfo, isLoading, error, regions, projectId } = useProjectGeneralInfo();

const { isAuthenticated } = useUserRole();

const { handleSubmit, setFieldValue, setValues, values, resetField } = useForm({
  validationSchema: formSchema,
  initialValues: {
    regions: {},
  },
});

const projectTypeValue = computed(() => values.type as ProjectType | null | undefined);

const { editProjectGeneralInfo, isEditProjectGeneralInfoLoading } = useEditProjectGeneralInfo();

const onSubmit = handleSubmit(async (values) => {
  const { regions, date_range, name, description, short_description, client, status, type, location_fips_codes } =
    values;
  const processedRegions = regions
    ? Object.entries(regions).map(([_, region]) => ({
        ...region,
      }))
    : [];
  const typedRegions =
    type === 'signature'
      ? processedRegions.map((item) => ({
          ...item,
          signatures_goal: item.signatures_goal || 0,
        }))
      : null;
  // processedRegions.map((item) => ({
  //     name: item.name,
  //     signatures_goal: item.signatures_goal || 0,
  //   }));
  const startDate = date_range.start;
  const endDate = date_range.end;
  await editProjectGeneralInfo({
    data: {
      name,
      description,
      short_description,
      client,
      status,
      start_date: startDate,
      end_date: endDate,
      regions: typedRegions,
      location_fips_codes: location_fips_codes?.length ? location_fips_codes : null,
    },
    projectId: projectId.value,
  }).catch((error) => {
    console.error('Error while editing project general info:', error);
  });
});

const dateRangePickerValue = ref<any>(undefined); //TODO: Define a more specific type if possible
const formRegions = ref<{ id: string }[]>([]); // doesn't work fine with computed, so using ref + watch

//TODO: check for implementation without watch
watch(
  () => projectGeneralInfo.value,
  (newItems) => {
    if (newItems) {
      const processedData = {
        date_range: { start: newItems.start_date, end: newItems.end_date },
        name: newItems.name,
        description: newItems.description,
        short_description: newItems.short_description,
        client: newItems.client,
        status: newItems.status,
        type: newItems.type,
        time_zone: newItems.time_zone,
        location_fips_codes: newItems.location_fips_codes,
      };
      setValues(processedData, false);
      dateRangePickerValue.value = processDateRangeValue({
        start: newItems.start_date,
        end: newItems.end_date,
      });
    }
  },
  { deep: true }
);

watch(
  () => regions.value,
  (newRegions) => {
    formRegions.value = newRegions?.map((_) => ({ id: crypto.randomUUID() }));
    formRegions.value.forEach((region, index) => {
      setFieldValue(`regions.${region.id}.name`, regions.value[index]?.name);
      if (isSignatureRegion(regions.value[index]))
        setFieldValue(`regions.${region.id}.signatures_goal`, regions.value[index]?.signatures_goal.toString());
    });
    if (values.regions) {
      const filteredRegions = Object.keys(values.regions)
        .filter((key) => formRegions.value.some((region) => region.id === key))
        .reduce((obj: Record<string, any>, key) => {
          obj[key] = values.regions![key];
          return obj;
        }, {});
      resetField('regions');
      setFieldValue('regions', filteredRegions, false);
    }
  },
  { deep: true }
);

const processedDataFromForm = computed(() => {
  const processedRegions = values.regions
    ? values.type === 'signature'
      ? Object.entries(values.regions).map(([key, region]) => ({
          name: region?.name,
          signatures_goal: Number(region?.signatures_goal?.toString().replaceAll(',', '')),
        }))
      : Object.entries(values.regions).map(([key, region]) => ({
          name: region?.name,
        }))
    : [];
  const startDate = values.date_range?.start;
  const endDate = values.date_range?.end;
  return {
    name: values.name,
    description: values.description,
    short_description: values.short_description,
    client: values.client,
    start_date: startDate,
    end_date: endDate,
    regions: values.type === 'signature' ? processedRegions : regions.value,
    status: values.status,
    type: values.type,
    time_zone: values.time_zone,
    location_fips_codes: values.location_fips_codes?.length ? [...values.location_fips_codes].sort() : null,
  };
});

// The picker emits a sorted selection, so sort the saved baseline too or the dirty-check churns on reorder.
const savedDataNormalized = computed(() => {
  if (!projectGeneralInfo.value) return projectGeneralInfo.value;
  return {
    ...projectGeneralInfo.value,
    location_fips_codes: projectGeneralInfo.value.location_fips_codes?.length
      ? [...projectGeneralInfo.value.location_fips_codes].sort()
      : null,
  };
});

function setDateRangePickerValue(value: { start?: string; end?: string }) {
  dateRangePickerValue.value = processDateRangeValue(value);
}
</script>

<style scoped lang="scss"></style>
