import { projectSchemaObject } from './project';
import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import type { ProjectStatus } from '~/client';

export const schemaObject = {
  ...projectSchemaObject,
  status: z.string({ message: 'Project Status is required' }).transform((val) => {
    return val as ProjectStatus;
  }),
};

export const formSchema = toTypedSchema(
  z.object(schemaObject).superRefine((data, ctx) => {
    const regionsList = Object.entries(data.regions || {});
    const isSignatureType = data.type === 'signature';
    if (regionsList.length > 0) {
      regionsList.forEach(([key, region]) => {
        if (isSignatureType && typeof region.signatures_goal !== 'number') {
          ctx.addIssue({
            code: z.ZodIssueCode.custom,
            message: 'Signatures goal is required for signature projects',
            path: ['regions', key, 'signatures_goal'],
          });
        }
      });
    }
  })
);
